Here's how to add a progress bar using the `cli-progress` package:

```typescript
import cliProgress from 'cli-progress';

function processFiles(files: string[]) {
  const bar = new cliProgress.SingleBar({
    format: 'Converting |{bar}| {percentage}% | {value}/{total} files',
    barCompleteChar: '█',
    barIncompleteChar: '░'
  });

  bar.start(files.length, 0);

  for (const file of files) {
    convertFile(file);
    bar.increment();
  }

  bar.stop();
  console.log('\nConversion complete!');
}
```

Use `chalk` for colored output:

```typescript
import chalk from 'chalk';

function log = {
  success: (msg: string) => console.log(chalk.green('✓'), msg),
  error: (msg: string) => console.log(chalk.red('✗'), msg),
  info: (msg: string) => console.log(chalk.blue('ℹ'), msg),
  warn: (msg: string) => console.log(chalk.yellow('⚠'), msg)
};

// Usage
log.success('File converted successfully');
log.error('Failed to read file: permission denied');
log.info('Processing 10 files...');
```
